read_enquiries_and_replies.source:
async function run(input, tools) {
  const settings = (input && input.settings) || {};
  const enquiriesSheet = settings.enquiries_sheet;
  const repliesSheet = settings.replies_sheet;
  if (!enquiriesSheet) return { oldest_new_enquiry: null };

  const enquiriesRes = await tools.sheets.read({ sheet: enquiriesSheet });
  const enquiries = (enquiriesRes && enquiriesRes.rows) || [];

  let replies = [];
  if (repliesSheet) {
    const repliesRes = await tools.sheets.read({ sheet: repliesSheet });
    replies = (repliesRes && repliesRes.rows) || [];
  }

  const norm = (v) => (v === null || v === undefined ? "" : String(v).trim().toLowerCase());
  const repliedContacts = new Set(replies.map((r) => norm(r && r.contact)).filter(Boolean));

  const candidates = enquiries.filter((row) => row && !repliedContacts.has(norm(row.contact)));
  if (candidates.length === 0) return { oldest_new_enquiry: null };

  const oldest = candidates[0];
  return {
    oldest_new_enquiry: {
      name: oldest.name ?? null,
      contact: oldest.contact ?? null,
      interest: oldest.interest ?? null,
      message: oldest.message ?? null
    }
  };
}

draft_reply.source:
async function run(input, tools) {
  const enquiry = input && input.oldest_new_enquiry;
  const settings = (input && input.settings) || {};
  if (!enquiry || typeof enquiry !== "object") {
    return { drafted_reply: "" };
  }
  const template = typeof settings.reply_template === "string" ? settings.reply_template : "";
  const name = enquiry.name == null ? "" : String(enquiry.name);
  const interest = enquiry.interest == null ? "" : String(enquiry.interest);
  const drafted = template
    .split("{name}").join(name)
    .split("{interest}").join(interest);
  return { drafted_reply: drafted };
}

prepare_approved_row.source:
async function run(input, tools) {
  const settings = input.settings || {};
  const enquiry = input.oldest_new_enquiry || {};
  const reply = typeof input.drafted_reply === "string" ? input.drafted_reply : "";
  const row = {
    name: enquiry.name ?? "",
    contact: enquiry.contact ?? "",
    reply: reply,
    status: "ready to send",
  };
  return {
    approved_row: {
      sheet: settings.replies_sheet || "replies",
      rows: [row],
      mode: "append",
    },
  };
}

prepare_skipped_row.source:
async function run(input) {
  const enquiry = input && input.oldest_new_enquiry;
  const settings = (input && input.settings) || {};
  const name = (enquiry && enquiry.name) != null ? enquiry.name : "";
  const contact = (enquiry && enquiry.contact) != null ? enquiry.contact : "";
  const skipped_row = {
    sheet: settings.replies_sheet,
    rows: [{ name, contact, reply: "", status: "skipped" }],
    mode: "append"
  };
  return { skipped_row };
}
